use std::io::*;

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut lines = s.lines();
    let c: usize = lines.next().unwrap().trim().parse().unwrap();
    // front = least recent, back = most recent
    let mut v: Vec<(i64, i64)> = Vec::new();
    let mut out = String::new();
    for l in lines {
        let p: Vec<&str> = l.split_whitespace().collect();
        if p.is_empty() {
            continue;
        }
        match p[0] {
            "put" => {
                let k: i64 = p[1].parse().unwrap();
                let val: i64 = p[2].parse().unwrap();
                if let Some(i) = v.iter().position(|e| e.0 == k) {
                    v.remove(i);
                }
                v.push((k, val));
                if v.len() > c {
                    let e = v.remove(0);
                    out.push_str(&format!("evict {}\n", e.0));
                }
            }
            "get" => {
                let k: i64 = p[1].parse().unwrap();
                if let Some(i) = v.iter().position(|e| e.0 == k) {
                    let e = v.remove(i);
                    v.push(e);
                    out.push_str(&format!("{}\n", e.1));
                } else {
                    out.push_str("-1\n");
                }
            }
            "keys" => {
                if v.is_empty() {
                    out.push_str("<empty>\n");
                } else {
                    let ks: Vec<String> = v.iter().rev().map(|e| e.0.to_string()).collect();
                    out.push_str(&ks.join(" "));
                    out.push('\n');
                }
            }
            _ => {}
        }
    }
    print!("{}", out);
}

